import assetIntegrity from './asset-integrity.mjs';
import tileAttribution from './tile-attribution.mjs';

// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library
// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like
// Leaflet.markercluster). Most are runtime behaviours with no repo-state
// signature and stay prose; the CDN wiring of the assets themselves is written
// into the HTML, and a tile layer's attribution is written into its own options
// object, so those convert. Fingerprinted by an actual Leaflet reference: a
// CDN asset (leaflet@ / leaflet.js / leaflet.css) in HTML, or a Leaflet API call
// site (L.map( / L.tileLayer( / L.markerClusterGroup() ) in source. The marker
// only *suspects* the pack; declaring it is the project's call, like every pack.

const LEAFLET_ASSET = /\bleaflet(\.js|\.css|@[\d.]|[-/]dist)/i;
const LEAFLET_API = /\bL\.(map|tileLayer|markerClusterGroup)\s*\(/;
const SOURCE = /\.(html?|mjs|cjs|jsx?|tsx?)$/;

export default {
  id: 'leaflet',
  ruleRoutingGuidance: {
    belongs: 'map rendering with the Leaflet library — map init options, tile layers, markers and divIcons, CDN plugin pinning',
    excludes: 'generic HTML markup rules — that is html; non-map dependency policy belongs to node',
  },
  badge: 'badge.svg',
  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',
  detect: (ctx) =>
    ctx.tracked.some((f) => {
      if (!SOURCE.test(f)) return false;
      const text = ctx.read(f);
      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));
    }),
  prose: 'RULES.md',
  worldRules: [assetIntegrity, tileAttribution],
};
=== README ===
# leaflet pack

Active when the repo references [Leaflet](https://leafletjs.com/) — a CDN asset (`leaflet@` / `leaflet.js` / `leaflet.css`) in HTML, or an `L.map` / `L.tileLayer` / `L.markerClusterGroup` call in JS/TS source. Mostly prose (these are runtime behaviours with no clean static signature); the CDN wiring of the assets themselves is written into the HTML, and a tile layer's attribution is written into its options object, so those are checks.

## Prose (`RULES.md`)

| Rule (≤5 words) | How enforced |
|---|---|
| Feature-detect plugin, fall back to core | prose |
| Embedded map: scrollWheelZoom false | prose |
| Keep tile attribution + maxZoom | check (`leaflet/tile-attribution`) for the attribution; prose for the provider's real `maxZoom` ceiling |
| divIcon transform on inner span | prose |

Provenance: distilled from `missingbulb/EdFringeNow` (the "Fringe Discover" static site — `index.html` CDN wiring and `js/app.js` map/marker/cluster code), the first fleet member seen using Leaflet.
=== schema ===
// THE PACK MANIFEST SPEC — the single declarative statement of what a
// `pack.mjs` may and must carry. Everything a pack declares about itself is
// described here once, and `validateManifest` is the only thing that judges a
// manifest against it. The loader calls it on every pack it imports (canon and a
// consumer's own `local_packs/` alike), so a malformed or incomplete manifest
// surfaces as a blocking `config` error at load — the same class as invalid JSON
// in `.claudinite-checks.json`.
//
// WHY A SPEC AND NOT A CHECK. A required manifest field is part of the pack
// contract, not a conformance opinion about a repo's content: a conformance rule
// would have to be declared BY a pack, run only when that pack is active, and
// re-derive the manifest by reading its source text — enforcing the shape of the
// system from inside one of its members. The spec is upstream of every pack, so
// there is nothing to declare and nothing to parse.
//
// Dependency-free by the engine's module rule: no imports, no filesystem. The
// caller supplies the facts from disk (the `skills/` directory listing), so this
// module is pure and testable standalone.

// The routing budget. Both sides of `ruleRoutingGuidance` are emitted as one row
// of a table every session loads (engine/pack_loader/inject-pack-prose.mjs), so
// the cap is a context cost, not a style preference: enough for a boundary and a
// pointer to the pack that owns the other side.
export const MAX_ROUTING_WORDS = 20;

// The two conformance scopes. A rule's scope is its PLACEMENT on the manifest —
// `worldRules` audit repo state, `workRules` judge the change and session in
// front of you — so the two runners' partition is declared where a reader of the
// pack can see it, and a rule module never restates (or contradicts) it.
export const RULE_SCOPES = { worldRules: 'world', workRules: 'work' };

const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isStringArray = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
const isRuleArray = (v) => Array.isArray(v) && v.every((x) => isPlainObject(x) && typeof x.id === 'string' && typeof x.run === 'function');

// Every field a manifest may carry. `required` fields must be present; the rest
// are validated only when declared. An UNDECLARED field is an error: the spec is
// the closed vocabulary of a pack, so a typo (`rule:`, `skill:`) fails loudly
// instead of being silently ignored forever.
export const PACK_FIELDS = {
